}

function spawnCopCar(G) {
  const a = G.rng.range(0, Math.PI * 2);
  const r = G.rng.range(500, 700);
  const v = makeVehicle(G.rng, 'police', G.player.x + Math.cos(a) * r, G.player.y + Math.sin(a) * r, 0);
  v.ai = null;
  G.vehicles.push(v);
